    description: { de: "Der Pambak fließt durch den Norden Armeniens und verbindet sich später mit dem Dsoraget zum Fluss Debed.", hu: "A Pambak folyó Észak-Örményországban folyik, majd a Dzoragettel egyesülve alkotja a Debed folyót.", ro: "Râul Pambak curge prin nordul Armeniei și se unește ulterior cu Dzoraget pentru a forma râul Debed.", en: "The Pambak flows through northern Armenia, later joining the Dzoraget to form the Debed River." , es: "El Pambak fluye por el norte de Armenia y más tarde se une al Dzoraget para formar el río Debed.", pt: "O Pambak corre pelo norte da Arménia e mais tarde junta-se ao Dzoraget para formar o rio Debed.", fr: "Le Pambak coule dans le nord de l'Arménie et rejoint plus tard le Dzoraguet pour former la rivière Debed."},
